import fs from "node:fs";

import { expect, test, uniqueName, sample } from "../../fixtures";

const TAG = "@DOC-04";
const TEN_MIB_PLUS_ONE = 10 * 1024 * 1024 + 1;

test.describe("upload vendor documents", () => {
  test("rejects an empty file with empty_file", { tag: TAG }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Empty"),
        category: "services",
        contact_email: `doc-empty-${Date.now().toString(36)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    // Act
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: { name: "empty.txt", mimeType: "text/plain", buffer: Buffer.alloc(0) },
      },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(422);
    expect((await res.json()).error.code).toBe("empty_file");
  });

  test("rejects a file of 10 MiB + 1 byte with file_too_large", { tag: TAG }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Large"),
        category: "services",
        contact_email: `doc-large-${Date.now().toString(36)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    // Act
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "too-large.txt",
          mimeType: "text/plain",
          buffer: Buffer.alloc(TEN_MIB_PLUS_ONE, 0x61),
        },
      },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(413);
    expect((await res.json()).error.code).toBe("file_too_large");
  });

  test("rejects a .exe file with unsupported_type", { tag: TAG }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Exe"),
        category: "services",
        contact_email: `doc-exe-${Date.now().toString(36)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    // Act
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "malware.exe",
          mimeType: "application/octet-stream",
          buffer: Buffer.from("MZ\u0000\u0000 not really an executable"),
        },
      },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(415);
    expect((await res.json()).error.code).toBe("unsupported_type");
  });

  test("rejects an unknown document kind with validation_error", { tag: TAG }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Doc Kind"),
        category: "services",
        contact_email: `doc-kind-${Date.now().toString(36)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    // Act
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "passport",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("w9.txt")),
        },
      },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(422);
    expect((await res.json()).error.code).toBe("validation_error");
  });
});
